// Write-through: we write to the cache AND the database at the same time
async function saveUser(id, data) {
  await db.user.update({ where: { id }, data });
  await cache.set(`user:${id}`, data); // synchronous, before continuing
}

// Write-back (write-behind): we write to the cache first, the database follows later
async function saveUserFast(id, data) {
  await cache.set(`user:${id}`, data);
  queue.push({ type: 'sync-db', id, data }); // deferred write, in the background
}

// Round-robin: each server receives requests in turn
servers = [serverA, serverB, serverC];
function roundRobin() {
  const server = servers[current % servers.length];
  current++;
  return server;
}

// Least connections: the request goes to the currently least-loaded server
function leastConnections() {
  return servers.reduce((min, s) => (s.activeConnections < min.activeConnections ? s : min));
}

